### 4.1 Parallel Upstream Calls

When a BFF endpoint requires data from multiple downstream services, use `Promise.all()` for parallel calls. Sequential calls add the latency of each call; parallel calls complete in the time of the slowest call.

```typescript
// src/api/controllers/dashboard.controller.ts
import { Request, Response, NextFunction } from 'express';
import { memberService } from '../../services/member.service';
import { careplanService } from '../../services/careplan.service';
import { claimsService } from '../../services/claims.service';
import { asyncRoute } from '../../utils/async-route';
import { AuthenticatedRequest } from '../middleware/auth.middleware';

interface DashboardResponse {
  member: MemberSummary;
  activePlans: CarePlanSummary[];
  recentClaims: ClaimSummary[];
}

export const getDashboard = asyncRoute(async (req: Request, res: Response) => {
  const { memberId } = (req as AuthenticatedRequest).jwtPayload;
  const correlationId = req.correlationId;

  // All three calls execute in parallel
  const [member, activePlans, recentClaims] = await Promise.all([
    memberService.getSummary(memberId, correlationId),
    careplanService.getActive(memberId, correlationId),
    claimsService.getRecent(memberId, { limit: 5 }, correlationId),
  ]);

  const response: DashboardResponse = {
    member,
    activePlans,
    recentClaims,
  };

  res.json(response);
});
```

**Error handling for parallel calls:**

`Promise.all()` rejects on the first rejection. If partial data is acceptable (the UI can render with some missing), use `Promise.allSettled()` and handle each result:

```typescript
const [memberResult, plansResult, claimsResult] = await Promise.allSettled([
  memberService.getSummary(memberId, correlationId),
  careplanService.getActive(memberId, correlationId),
  claimsService.getRecent(memberId, { limit: 5 }, correlationId),
]);

const response: Partial<DashboardResponse> = {};

if (memberResult.status === 'fulfilled') {
  response.member = memberResult.value;
} else {
  logger.warn({ err: memberResult.reason, correlationId }, 'Member service call failed');
}

if (plansResult.status === 'fulfilled') {
  response.activePlans = plansResult.value;
}

if (claimsResult.status === 'fulfilled') {
  response.recentClaims = claimsResult.value;
}
```

