### 8.1 Circuit Breaker Implementation

Use `cockatiel` (a TypeScript-native resilience library) to implement the circuit breaker:

```typescript
// src/infrastructure/resilience/circuit-breaker.ts
import {
  CircuitBreakerPolicy,
  ConsecutiveBreaker,
  ExponentialBackoff,
  Policy,
  retry,
  circuitBreaker,
  handleAll,
  wrap,
} from 'cockatiel';

export function createResiliencePolicy(
  name: string,
  options: { maxRetries?: number; breakerThreshold?: number } = {}
): ReturnType<typeof wrap> {
  const retryPolicy = retry(handleAll, {
    maxAttempts: options.maxRetries ?? 2,
    backoff: new ExponentialBackoff({ maxDelay: 2000 }),
  });

  const breakerPolicy = circuitBreaker(handleAll, {
    halfOpenAfter: 10_000,
    breaker: new ConsecutiveBreaker(options.breakerThreshold ?? 5),
  });

  return wrap(retryPolicy, breakerPolicy);
}
```

```typescript
// src/services/member.service.ts
import { createResiliencePolicy } from '../infrastructure/resilience/circuit-breaker';
import { MemberHttpClient } from '../infrastructure/http/member.http-client';

const memberCircuitBreaker = createResiliencePolicy('member-service', { maxRetries: 2 });

export async function getMemberSummary(
  memberId: string,
  accessToken: string,
  correlationId: string
): Promise<MemberSummary> {
  return memberCircuitBreaker.execute(() =>
    memberClient.getSummary(memberId, accessToken, correlationId)
  );
}
```

